      change (mkRr (RV yra ysp ygp ytp yt0 yt1 yt2 ys0 ys1 ya0 ya1 ya2 ya3 ya4 ya5 ya6 ya7 ys2 ys3 ys4 ys5 ys6 ys7 ys8 ys9 ys10 ys11 yt3 yt4 yt5 yt6))
        with (mkR yra ysp ygp ytp yt0 yt1 yt2 ys0 ys1 ya0 ya1 ya2 ya3 ya4 ya5 ya6 ya7 ys2 ys3 ys4 ys5 ys6 ys7 ys8 ys9 ys10 ys11 yt3 yt4 yt5 yt6) in *;
      cbn [rra rsp rgp rtp rt0 rt1 rt2 rs0 rs1 ra0 ra1 ra2 ra3 ra4 ra5 ra6 ra7 rs2 rs3 rs4 rs5 rs6 rs7 rs8 rs9 rs10 rs11 rt3 rt4 rt5 rt6] in *.
    Ltac to_rv_in E := lazymatch type of E with _ = MS ?R _ _ _ _ _ _ => let r := rv_of R in change R with (mkRr r) in E end.
    Ltac splits Hx := nd_splits Hx.   (* [comment removed for export] *)
    Ltac disj LV := try (destruct LV as [LV|LV]; [| disj LV]).
    Ltac leaf_openN P r1 m1 E1 :=
      let pc1 := fresh "pc1" in let LV := fresh "LV" in
      destruct P as (pc1 & r1 & m1 & E1 & LV); disj LV; splits LV; subst pc1;
      cbn [rra rsp rgp rtp rt0 rt1 rt2 rs0 rs1 ra0 ra1 ra2 ra3 ra4 ra5 ra6 ra7 rs2 rs3 rs4 rs5 rs6 rs7 rs8 rs9 rs10 rs11 rt3 rt4 rt5 rt6] in *.
    Ltac name_leaf m1 :=
      match goal with X : munch _ _ m1 |- _ => rename X into MUl end;
      match goal with X : wmono _ _ m1 |- _ => rename X into WMl end;
      match goal with X : mem_inv _ m1 |- _ => rename X into MIl end;
      try match goal with X : stk _ m1 _ _ |- _ => rename X into STl end.
    Ltac breg1 := first [ eassumption | reflexivity
                        | etransitivity; [eassumption| first [eassumption | reflexivity | f_equal; lia | apply bv_eq; rewrite ?unsigned_lit by lia; lia]] ].
